comp={'A':'T','T':'A','G':'C','C':'G'}
def rc(s): return "".join(comp[b] for b in reversed(s))

# Inverted repeats / palindromes (hairpin potential), arm >= 12, loop <= 60
print("Inverted repeats (arm>=12, gap<=50):")
hits=[]
for i in range(N):
    for arm in range(12,60):
        if i+arm>N: break
        left=seq[i:i+arm]
        # search right arm rc downstream
        target=rc(left)
        j=seq.find(target, i+arm, min(N,i+arm+50))
        if j!=-1:
            hits.append((i,j,arm,j-(i+arm)))
# keep maximal non-redundant
hits.sort(key=lambda x:(-x[2]))
kept=[]
for h in hits:
    if all(not (h[0]>=k[0] and h[1]<=k[1]) for k in kept):
        kept.append(h)
for h in kept[:15]:
    print(f"arm {h[2]}bp: pos {h[0]}-{h[0]+h[2]} pairs with {h[1]}-{h[1]+h[2]} (loop {h[3]})")

