import random, statistics
seq="".join(l.strip() for l in open("region.fasta") if not l.startswith(">"))
N=len(seq)
stop={"TAA","TAG","TGA"}
def longest_orf(s):
    best=0
    for f in range(3):
        i=f;start=None;L=len(s)
        while i+3<=L:
            cod=s[i:i+3]
            if start is None:
                if cod=="ATG": start=i
            else:
                if cod in stop:
                    best=max(best,i+3-start);start=None
            i+=3
        if start is not None: best=max(best,L-start)
    return best
obs=longest_orf(seq)
letters=list(seq);vals=[]
for _ in range(50):
    random.shuffle(letters);vals.append(longest_orf("".join(letters)))
print("observed longest ORF (bp):",obs)
print("shuffled: mean %.0f  min %d  max %d"%(statistics.mean(vals),min(vals),max(vals)))
print("observed percentile:", round(100*sum(v<=obs for v in vals)/len(vals),1))
